parameters.text:
=Coding task {{ $json.coding_task_id }} for claim {{ $json.claim_id }}
Encounter id (FHIR): {{ $json.encounter_id }} · Patient id (FHIR): {{ $json.patient_id }}
Setting: {{ $json.setting }} · Date of service: {{ $json.date_of_service }}

Propose the diagnosis and procedure codes for this encounter, each with a rationale and a citation to the source document.

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "codes": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "system": {
            "type": "string",
            "enum": [
              "ICD-10-CM",
              "CPT",
              "HCPCS"
            ],
            "description": "Code system."
          },
          "code": {
            "type": "string",
            "description": "The code, with the decimal point for ICD-10-CM (for example E11.65)."
          },
          "role": {
            "type": "string",
            "enum": [
              "principal_diagnosis",
              "secondary_diagnosis",
              "procedure"
            ],
            "description": "How the code is used on the claim."
          },
          "modifiers": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "CPT or HCPCS modifiers, empty for diagnoses."
          },
          "units": {
            "type": "integer",
            "description": "Units of service. 1 for diagnoses."
          },
          "source_document_id": {
            "type": "string",
            "description": "Id of the source document that supports the code."
          },
          "source_excerpt": {
            "type": "string",
            "description": "Shortest supporting quote from that document, at most 200 characters."
          },
          "rationale": {
            "type": "string",
            "description": "One sentence on why this code."
          }
        },
        "required": [
          "system",
          "code",
          "role",
          "modifiers",
          "units",
          "source_document_id",
          "source_excerpt",
          "rationale"
        ],
        "additionalProperties": false
      },
      "description": "Proposed codes, principal diagnosis first."
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1. How sure you are that the recommendation is right given what the tools returned. Below 0.5 means you are guessing."
    },
    "rationale": {
      "type": "string",
      "description": "Two to five sentences a reviewer can check against the tool results. Cite the record ids you relied on."
    },
    "questions_for_human": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "If a person has to decide, the specific questions they need to answer. Empty when nothing is open."
    }
  },
  "required": [
    "codes",
    "confidence",
    "rationale",
    "questions_for_human"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let out = null;
try { out = one('Medical coding agent').output ?? null; } catch (e) {} // unreadable output is treated as none

const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = one('Normalize coding task'); // one(): defined by guardPreamble; survives a lost item link
const task = $json; // fresh read of the coding task
const codes = out?.codes ?? [];
const docs = new Set((task.document_ids ?? []).map(String));
const FORMAT = {
  'ICD-10-CM': /^[A-TV-Z][0-9][0-9A-Z](\.[0-9A-Z]{1,4})?$/,
  CPT: /^[0-9]{4}[0-9FTU]$/,
  HCPCS: /^[A-V][0-9]{4}$/,
};

if (task.status !== 'open') reasons.push('coding task status is now ' + task.status);
if (!['draft', 'pending_coding'].includes(task.claim_status)) reasons.push('claim status is ' + task.claim_status + '; codes can only be added before the claim is released');
if (String(task.claim_id) !== req.claim_id) reasons.push('task points at claim ' + task.claim_id + ', not ' + req.claim_id);
if (out) {
  if (!codes.length) reasons.push('no codes proposed');
  if (codes.length > cfg.max_codes) reasons.push(codes.length + ' codes proposed, limit ' + cfg.max_codes);
  const principal = codes.filter((c) => c.role === 'principal_diagnosis');
  if (principal.length !== 1) reasons.push(principal.length + ' principal or first-listed diagnoses, expected exactly 1');
  const seen = new Set();
  codes.forEach((c, i) => {
    // Position and system, not the code itself: reasons reach Slack through the hand-off.
    const label = 'code ' + (i + 1) + ' (' + c.system + ')';
    if (!FORMAT[c.system]?.test(c.code)) reasons.push(label + ' is not a well-formed ' + c.system + ' code');
    const isDx = c.system === 'ICD-10-CM';
    if (isDx && c.role === 'procedure') reasons.push(label + ' is a diagnosis code used as a procedure');
    if (!isDx && c.role !== 'procedure') reasons.push(label + ' is a procedure code used as a diagnosis');
    if (!isDx && !(Number.isInteger(c.units) && c.units >= 1)) reasons.push(label + ' has invalid units');
    for (const m of c.modifiers ?? []) if (isDx || !/^[0-9A-Z]{2}$/.test(m)) reasons.push(label + ' has an invalid modifier');
    if (!c.source_document_id) reasons.push(label + ' has no source citation');
    else if (!docs.has(String(c.source_document_id))) reasons.push(label + ' cites document ' + c.source_document_id + ', which is not a source document for this encounter');
    if (!String(c.source_excerpt ?? '').trim()) reasons.push(label + ' has no supporting excerpt');
    const key = c.system + ' ' + c.code + ' ' + (c.modifiers ?? []).join(',');
    if (seen.has(key)) reasons.push(label + ' duplicates an earlier code');
    seen.add(key);
  });
}

const normalized = codes.map((c) => ({ system: c.system, code: c.code, role: c.role, modifiers: c.modifiers ?? [], units: c.system === 'ICD-10-CM' ? 1 : c.units, source_document_id: c.source_document_id }));
const action = { type: 'write_codes', claim_id: req.claim_id, coding_task_id: req.coding_task_id, encounter_id: req.encounter_id, codes: normalized };
const dx = normalized.filter((c) => c.system === 'ICD-10-CM').length;
// Counts and ids only. The coder reviews codes, excerpts and rationale in the coding worklist.
const summary = 'Claim ' + req.claim_id + ' · task ' + req.coding_task_id + ' · ' + req.setting + ', date of service ' + req.date_of_service + '\n'
  + 'Proposed: *' + dx + ' diagnosis codes and ' + (normalized.length - dx) + ' procedure codes*, each cited to a source document. Review them in the coding worklist before approving.';
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
// Read the plan even if n8n lost the item link (seen live after the AI Agent node).
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
const planned = one('Guardrails').action;
const key = (c) => [c.system, c.code, c.role, (c.modifiers ?? []).join(','), c.units ?? 1].join('|');
const want = planned.codes.map(key).sort();
const got = ($json.codes ?? []).map(key).sort();
const ok = JSON.stringify(want) === JSON.stringify(got);
const missing = want.filter((k) => !got.includes(k));
const extra = got.filter((k) => !want.includes(k));
const detail = 'claim codes differ from the approved set: ' + missing.length + ' missing, ' + extra.length + ' unexpected';
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
// Every lookup is guarded: this node is the safety net, so it must never be the step that fails.
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let intake = null;
let agent = null;
let guard = null;
try { intake = one('Normalize coding task'); } catch (e) {}
try { agent = one('Medical coding agent'); } catch (e) {}
try { guard = one('Guardrails'); } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if (!intake) {
  // n8n could not link this item back to its request. Keep whatever identifies it and say so.
  intake = { business_key: $json.business_key ?? null };
  reasons.push('item_context_lost: the request could not be linked to this failure; check the n8n execution');
}
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const REDACT = [].map((p) => new RegExp(p, 'g'));
const scrub = (text) => REDACT.reduce((t, r) => t.replace(r, '[redacted]'), String(text ?? ''));
// The masks also apply to what the model wrote, in case it repeated a number it read.
const scrubJson = (v) => {
  if (!REDACT.length || v == null) return v;
  try { return JSON.parse(scrub(JSON.stringify(v))); } catch (e) { return scrub(JSON.stringify(v)); }
};
const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: scrub(s.observation).slice(0, 1500),
}));

const summary = 'Claim ' + intake.claim_id + ' · task ' + intake.coding_task_id + ' · ' + ((agent?.output?.codes ?? []).length) + ' codes proposed';
// Slack-safe copies: request, document and model text can contain Slack markup such as <!channel>.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return {
  json: {
    business_key: intake.business_key,
    team: "coding operations",
    reasons,
    proposed: scrubJson(agent?.output ?? null),
    confidence: agent?.output?.confidence ?? null,
    questions: scrubJson(agent?.output?.questions_for_human ?? []),
    trace,
    summary,
    slack: { key: esc(intake.business_key), summary: esc(summary), reasons: esc(reasons.join('; ')) },
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

